/** A reward is generated by the server; it must never be a client-priced product. */
export const KEYCHAIN_REWARD_THRESHOLD = 80;
export const KEYCHAIN_REWARD_PRODUCT_ID = "nfc-keychain";
export const KEYCHAIN_REWARD_QR_DESTINATION = "https://skanare.com/";

export function merchandiseSubtotal(items = []) {
  return Math.round(items.reduce((sum, item) => {
    if (item.isFreeReward) return sum;
    return sum + Math.max(0, Number(item.price || 0)) * Math.max(0, Number(item.quantity || 0));
  }, 0) * 100) / 100;
}

export function qualifiesForKeychain(subtotal) {
  return Number.isFinite(Number(subtotal)) && Number(subtotal) >= KEYCHAIN_REWARD_THRESHOLD;
}

export function freeKeychainItem(product, variant = null) {
  const images = Array.isArray(product.images) ? product.images : [];
  return {
    id: "reward:nfc-keychain",
    productId: KEYCHAIN_REWARD_PRODUCT_ID,
    title: product.title || "NFC Keychain",
    image: images[0] || product.image || "/assets/img/logo_Image.png",
    quantity: 1,
    price: 0,
    originalPrice: Number(product.price || 0),
    currency: "EUR",
    isFreeReward: true,
    variant: variant ? { sku: variant.sku || "", size: variant.size || "", color: variant.color || "" } : null,
    qrDestination: KEYCHAIN_REWARD_QR_DESTINATION,
    customQr: Boolean(product.customQr),
  };
}

export function availableKeychainVariant(product) {
  const variants = Array.isArray(product?.variants) ? product.variants : [];
  if (variants.length) {
    return variants.find((v) => Number(v.stock || 0) > 0) || null;
  }
  return Number(product?.stock || 0) > 0 ? undefined : null;
}
